    {"id":"dc84737c-e88a-4917-83a6-15cf21cd1002","number":19,"title":"Açúcar no Violão","originalArtist":"Café Frio & Cia","musicalKey":"Dm","bpm":79,"estimatedDurationMs":373000,"youtubeReference":null,"lyricStatus":"static","lyrics":{"blocks":[{"id":"b09a3b2e-be92-42ea-8072-65a08ceb4538","name":"Verso 1","lines":[{"id":"95571b10-7000-412e-84bd-6bc55592fcd2","text":"Troquei a colher pela palheta sem querer","startTimeMs":null},{"id":"316da8c5-4277-46ae-82da-bd1ed94cb06b","text":"O violão ficou doce antes do amanhecer","startTimeMs":null},{"id":"63259de4-ef17-4136-87f1-395c80ed6407","text":"Na mesa, duas xícaras guardavam a estação","startTimeMs":null},{"id":"485e47ec-0bd0-4093-8d46-82fa7845f3c6","text":"E uma corda de nylon adoçou meu coração","startTimeMs":null},{"id":"34ad6573-4d5f-4ad1-8cb4-bfa455a368fa","text":"","startTimeMs":null}]},{"id":"2039e532-9652-43ad-8373-b80dd99c6557","name":"Pré-refrão","lines":[{"id":"0ebf1d6f-c10a-46b2-8d7b-d77dd626ca58","text":"A tarde demora no vidro da janela","startTimeMs":null},{"id":"0cb44f2d-2d64-47bd-85a0-95ee9e981525","text":"Um raio de sol mexe a colher dela","startTimeMs":null}]},{"id":"97329588-6c73-4325-81e7-277f11a7f3d0","name":"Refrão","lines":[{"id":"4700c0d5-8d4d-4a17-843d-63b1fc04744a","text":"Põe açúcar no violão, deixa a tarde ficar","startTimeMs":null,"bold":true},{"id":"e2eec020-2972-4706-8585-5029757e1470","text":"Se o café esfriou, a conversa esquentou","startTimeMs":null},{"id":"cc1e34e7-cd59-4a90-83ea-f8b67c168441","text":"Põe açúcar no violão, deixa a tarde ficar","startTimeMs":null},{"id":"a0438a64-5e1f-4e80-8cce-143cac53a0c9","text":"E o tempo, quietinho, sentou","startTimeMs":null}]},{"id":"5147763c-a4a5-48f0-8b72-55f132179869","name":"Verso 2","lines":[{"id":"6742aa46-9804-4b38-8ad5-3ecd0d7a4faa","text":"Na mesa, duas xícaras guardavam a estação","startTimeMs":null},{"id":"7430a1a4-266b-4862-8844-8ead26ad21d3","text":"Há um silêncio bonito entre duas canções","startTimeMs":null},{"id":"aa162ce7-43e5-